    # Uniform rows and columns act as separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, separators):
        cuts = [-1] + separators + [size]
        return [(cuts[i] + 1, cuts[i + 1]) for i in range(len(cuts) - 1)
                if cuts[i] + 1 < cuts[i + 1]]

    row_ranges = segments(h, sep_rows)
    col_ranges = segments(w, sep_cols)
    out = [row[:] for row in grid]

    # The common background is the most frequent color in the grid.
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find a tile containing a pattern, then repeat it in every tile.
    pattern = None
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            tile = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            marked = [(i, j, tile[i][j])
                      for i in range(len(tile)) for j in range(len(tile[0]))
                      if tile[i][j] != background]
            if marked:
                pattern = marked
                break
        if pattern:
            break

    if pattern:
        for r0, r1 in row_ranges:
            for c0, c1 in col_ranges:
                for i, j, color in pattern:
                    if r0 + i < r1 and c0 + j < c1:
                        out[r0 + i][c0 + j] = color

    return out
