def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def ranges(n, separators):
        result, start = [], 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rr, cc = ranges(h, sep_rows), ranges(w, sep_cols)
    out = [row[:] for row in grid]

    source = None
    for r0, r1 in rr:
        for c0, c1 in cc:
            marks = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1)
                     for c in range(c0, c1)
                     if grid[r][c] != background]
            if marks:
                source = marks
                break
        if source is not None:
            break

    if source:
        for r0, r1 in rr:
            for c0, c1 in cc:
                for dr, dc, color in source:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = color
    return out
